CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;
CREATE TABLE public.market_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL, source_url text, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.market_documents TO authenticated;
GRANT ALL ON public.market_documents TO service_role;
ALTER TABLE public.market_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY market_documents_owner ON public.market_documents FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.market_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES public.market_documents(id) ON DELETE CASCADE, user_id uuid NOT NULL DEFAULT auth.uid(), chunk_index integer NOT NULL, content text NOT NULL, embedding public.vector(3072) NOT NULL, embedding_model text NOT NULL DEFAULT 'google/gemini-embedding-2', UNIQUE(document_id,chunk_index));
GRANT SELECT,INSERT,DELETE ON public.market_chunks TO authenticated;
GRANT ALL ON public.market_chunks TO service_role;
ALTER TABLE public.market_chunks ENABLE ROW LEVEL SECURITY;
CREATE POLICY market_chunks_owner ON public.market_chunks FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.market_documents d WHERE d.id = document_id AND d.user_id = auth.uid()));
CREATE INDEX market_chunks_vector_idx ON public.market_chunks USING hnsw ((embedding::public.halfvec(3072)) public.halfvec_cosine_ops);
CREATE INDEX market_documents_owner_idx ON public.market_documents(user_id);
CREATE OR REPLACE FUNCTION public.match_market_chunks(query_embedding public.vector(3072), match_count integer DEFAULT 6) RETURNS TABLE(id uuid, document_id uuid, title text, source_url text, content text, similarity double precision) LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$ SELECT c.id,c.document_id,d.title,d.source_url,c.content,1-(c.embedding::public.halfvec(3072) <=> query_embedding::public.halfvec(3072)) AS similarity FROM public.market_chunks c JOIN public.market_documents d ON d.id=c.document_id WHERE c.user_id=auth.uid() AND d.user_id=auth.uid() AND c.embedding_model='google/gemini-embedding-2' ORDER BY c.embedding::public.halfvec(3072) <=> query_embedding::public.halfvec(3072) LIMIT least(greatest(match_count,1),6); $$;
REVOKE ALL ON FUNCTION public.match_market_chunks(public.vector,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.match_market_chunks(public.vector,integer) TO authenticated;
CREATE TABLE public.market_ai_access (user_id uuid PRIMARY KEY DEFAULT auth.uid(), message text NOT NULL, status integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.market_ai_access TO authenticated;
GRANT ALL ON public.market_ai_access TO service_role;
ALTER TABLE public.market_ai_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY market_ai_access_owner ON public.market_ai_access FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());